@HiltWorker
class ExportWorker @AssistedInject constructor(
  @Assisted appContext: Context,
  @Assisted params: WorkerParameters,
  private val repo: ExportRepo
) : CoroutineWorker(appContext, params) {

  override suspend fun doWork(): Result = try {
    repo.export { percent -> setProgress(workDataOf("percent" to percent)) }
    Result.success()
  } catch (e: IOException) {
    Result.retry()                       // transient: offline, timeout
  } catch (e: HttpException) {
    Result.failure()                     // 4xx will never succeed on retry
  }
}

val request = OneTimeWorkRequestBuilder<ExportWorker>()
  .setConstraints(
    Constraints.Builder()
      .setRequiredNetworkType(NetworkType.CONNECTED)
      .build()
  )
  .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
  .build()

// Unique name: repeated taps do not queue fifty exports
WorkManager.getInstance(context)
  .enqueueUniqueWork("export", ExistingWorkPolicy.KEEP, request)

// Observe progress from the UI
val info = WorkManager.getInstance(context)
  .getWorkInfoByIdFlow(request.id)
  .collectAsStateWithLifecycle(initialValue = null)

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    handle(intent)                                  // cold start
    setContent { AppRoot() }
  }

  override fun onNewIntent(intent: Intent) {        // already running, singleTop
    super.onNewIntent(intent)
    handle(intent)
  }

  private fun handle(intent: Intent) {
    val uri = intent.data ?: return
    // attacker-controlled input: validate, and re-check authorization server-side
    val orderId = uri.pathSegments.getOrNull(1)?.toLongOrNull() ?: return
    Router.openOrder(orderId)
  }
}

