class ScannerActivity : ComponentActivity() {

  // Wrong: in split screen both apps are RESUMED, so both grab the camera
  // override fun onResume() { super.onResume(); openCamera() }
  // override fun onPause() { releaseCamera(); super.onPause() }

  // Right: only one activity is top-resumed at a time
  override fun onTopResumedActivityChanged(isTopResumedActivity: Boolean) {
    super.onTopResumedActivityChanged(isTopResumedActivity)
    if (isTopResumedActivity) openCamera() else releaseCamera()
  }

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    // Visibility-scoped work still belongs to STARTED, not to top-resumed
    lifecycleScope.launch {
      repeatOnLifecycle(Lifecycle.State.STARTED) { viewModel.frames.collect(::render) }
    }
  }

  override fun onMultiWindowModeChanged(isInMultiWindowMode: Boolean, newConfig: Configuration) {
    super.onMultiWindowModeChanged(isInMultiWindowMode, newConfig)
    layoutForWidth(newConfig.screenWidthDp)
  }

  private fun openCamera() = cameraManager.openCamera(
    cameraId,
    object : CameraDevice.StateCallback() {
      override fun onOpened(device: CameraDevice) { startPreview(device) }
      // Ownership is never guaranteed — react to eviction, do not assume it cannot happen
      override fun onDisconnected(device: CameraDevice) { device.close(); showRetry() }
      override fun onError(device: CameraDevice, error: Int) { device.close(); showError(error) }
    },
    handler
  )
}

